        self._sigim = sigim
        self._jami = 0

    def qoyish(self, x):
        if self._jami + x > self._sigim:
            return False
        self._jami += x
        return True

    def olish(self, x):
        self._jami -= x
        return True

    def miqdor(self):
        return self._jami


