import java.util.Scanner;

public class Main {
    static class Ombor {
        private long jami = 0;
        private final long sigim;

        Ombor(long sigim) {
            this.sigim = sigim;
        }

        boolean qoyish(long x) {
            if (jami + x > sigim) return false;
            jami += x;
            return true;
        }

        boolean olish(long x) {
            jami -= x;
            return true;
        }

        long miqdor() {
            return jami;
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Ombor ombor = new Ombor(in.nextLong());
        int n = in.nextInt();
        for (int i = 0; i < n; i++) {
            long d = in.nextLong();
            if (d > 0) System.out.println(ombor.qoyish(d) ? "ok" : "error");
            else System.out.println(ombor.olish(-d) ? "ok" : "error");
        }
        System.out.println(ombor.miqdor());
    }
}

