#include <iostream>
using namespace std;

class Ombor {
    long long jami = 0;
    long long sigim;

public:
    Ombor(long long sigim) : sigim(sigim) {}

    bool qoyish(long long x) {
        if (jami + x > sigim) return false;
        jami += x;
        return true;
    }

    bool olish(long long x) {
        jami -= x;
        return true;
    }

    long long miqdor() const {
        return jami;
    }
};

int main() {
    long long c;
    int n;
    cin >> c >> n;
    Ombor ombor(c);
    for (int i = 0; i < n; i++) {
        long long d;
        cin >> d;
        if (d > 0) cout << (ombor.qoyish(d) ? "ok" : "error") << endl;
        else cout << (ombor.olish(-d) ? "ok" : "error") << endl;
    }
    cout << ombor.miqdor() << endl;
    return 0;
}

